t       10 : *substitute_award #奖励列表\n    }\n}\n\n#重置上一波超频战场\nreset_last_substitution 10316 {\n    request {\n        mode    0 : integer\n    }\n    response {\n        result          0 : integer\n        levelmode       1 : modeconfig\n        score_toweek    2 : integer         #本周最高积分\n        status          3 : integer         #当前战斗状态(0 未战斗 1 战斗中)\n        bosshp          4 : string          #本场战斗boss剩余血量\n        score           5 : integer         #本场战斗积分\n        fightcount      6 : integer         #本场战斗进行次数\n        unlocklevel     7 : integer         #boss解锁等级\n        curlevel        8 : integer         #当前所在等级\n\n        .scoreup {\n            servantid   0 : integer\n            up          1 : string\n        }\n        uplist          9 : *scoreup        #当前up列表\n        awardlist       10 : *substitute_award #奖励列表\n    }\n}\n\n#同步超频战场时间\nsync_substitution_time 10317 {\n    request {\n        dt      0 : string\n        damage  1 : string\n    }\n    response {\n        result          0 : integer\n        time            1 : string\n        levelmode       2 : modeconfig\n        score_toweek    3 : integer\n        newscore        4 : boolean\n        status          5 : integer\n        bosshp          6 : string\n        score           7 : integer\n        fightcount      8 : integer\n        unlocklevel     9 : integer\n        curlevel        10 : integer\n        awardlist       11 : *substitute_award\n        .item_res {\n            gold    0 : integer\n            diamond 1 : integer\n            items   2 : *item\n        }\n        item_res        12 : item_res          #自动领取已完成的奖励\n    }\n}\n\n#获取极限拟练阵容\nget_old_substitution_battlearray 10318 {\n    response {\n        result 0 : integer\n        array 1 : *battle_array\n    }\n}\n\nset_old_substitution_servant 10319 {\n    request {\n        array 0 : integer\n        pos 1 : integer\n        servantid 2 : integer\n    }\n    response {\n        result 0 : integer\n        array 1 : 