动(201)\n#buff结构\n.plague_buff {\n    buffid  0 : integer #buffid\n    time    1 : integer #到期时间  时间戳\n    round   2 : integer #剩余回合\n}\n\n#城市基础信息\n.plague_city_base {\n    cityid          0 : integer #城市id\n    damage          1 : integer #破坏度\n    decode          2 : integer #破译度\n    story           3 : boolean #标记是否已过剧情\n    next_round_time 4 : integer #时间戳  -1 表示该城市还没投放病毒\n}\n\n#瘟疫消息结构\n.plague_news {\n    id      1 : integer #参数列表\n    new     2 : boolean #新标记\n    cityid  3 : integer\n    nodeid  4 : integer\n    seconds 5 : integer\n    nodeids 6 : *integer\n    coin    7 : integer\n    damage  8 : integer\n}\n\n#病毒结构\n.plague_virus_base {\n    virusid 0 : integer #病毒id\n    num     1 : integer(1) #数量\n}\n\n#节点基础信息\n.plague_node_info {\n    nodeid          0 : integer #节点id\n    damage          1 : integer #当前破坏度\n    damage_remain   2 : integer #完全破坏剩余时间 单位 秒 -1 表示还没开始破坏\n    invadeids       3 : *integer #上轮入侵的节点id\n    viruses         4 : *plague_virus_base #该节点携带病毒信息\n    breed           5 : integer(1) #繁育速度\n    defense         6 : integer #节点防御力\n    buffs           7 : *plague_buff #节点上附带的buff列表\n    capacity        8 : integer #容量\n}\n\n#进入模块时获取的基础信息\nget_plague_info 20101 {\n    request {\n        id 0 : integer #活动id\n    }\n    response {\n        result      0 : integer #0 失败,活动时间未到\n        cities      1 : *plague_city_base\n        news        2 : plague_news #消息\n        output      3 : integer #每小时产出\n        lastrecover 4 : integer #病毒上次恢复时间\n        virusbuy    5 : integer #剩余购买次数\n        virusmax    6 : integer #最大可恢复病毒数量\n    }\n}\n\n\n#获取城市详情 玩家在这个系统的时候 根据每个城市的next_round_time来发送这个请求\nget_plague_city_info 20102 {\n    request {\n        id      0 : integer #活动id\n        cityid  1 : integer #城市id\n    }\n    response {\n        result          0 : integer #1 成功 2 城市未解锁\n        next_round_time 1 : integer #下一轮时间 时间戳\n        nodes           2 : *plague_node_info #城市节点信息\n        decode          3 : integer #破译度\n        decode_reamin   4 : integer #破译剩余时间 单位 秒\n        damage          5 : integer #破坏度\n        buffs           6 : *plague_buff #城市附带的buff列表\n        news            7 : plague_news #消息\n        story           8 : boolean #标记是否已过剧情\n    }\n}\n\n#投放病毒\nplague_delivery_virus 20103 {\n    request {\n        id          0 : integer #活动id\n        cityid      1 : integer #城市id\n        nodeid      2 : integer #节点id\n        virusid     3 : integer #病毒id\n        num         4 : integer #投放数量\n    }\n    response {\n        result          0 : integer #0 失败 1 成功 2 失败 病毒数量不足 3 失败 节点防御过高 4 失败 节点已满 5 城市未解锁 6 城市当前状态不能投放病毒 7 节点不存在\n        node            1 : plague_node_info #当前节点的信息更新\n        next_round_time 2 : integer #节点所在城市的下次刷新时间\n        stock_cost      3 : *consumeids #消耗的病毒\n    }\n}\n\n#完成城市的剧情\nplague_finish_city_story 20104 {\n    request {\n        id      0 : integer #活动id\n        cityid  1 : integer\n    }\n    response {\n        result      0 : integer\n        cities      1 : *plague_city_base #新解锁的城市列表\n        virusmax    2 : integer #最大可恢复病毒数量virusmax\n    }\n}\n\n#获取成就奖励信息\nget_plague_achievement_info 20105 {\n    request {\n        id 0 : integer #活动id\n    }\n    response {\n        .info {\n            cityid  0 : integer #城市信息\n            record  1 : integer #破坏度最高记录\n            step    2 : integer #领奖个数\n        }\n        result  0 : integer #0 失败,活动时间未到\n        list    1 : *info #成就列表 激活的城市才会在此列表 此列表不是完整列表\n    }\n}\n\n#领取成就奖励\nget_plague_achievement_reward 20106 {\n    request {\n        id      0 : integer #活动id\n        cityid  1 : integer #城市id\n    }\n    response {\n        result  0 : integer #结果 0 失败 1 成功 2 失败 未到达要求 3 奖励已领完 4 城市未解锁\n        cityid  1 : integer\n        step    2 : integer #当前已经领取的个数\n        items   3 : *item #获得的物品\n    }\n}\n\n#获取消息中心信息\nget_plague_news 20107 {\n    request {\n        id      0 : integer #活动id\n        start   1 : integer #起始的index(1是第一个)\n        count   2 : integer #数量\n    }\n    response {\n        result  0 : integer #0 失败,活动时间未到\n        total   1 : integer #新闻总条数\n        list    2 : *plague_news\n    }\n}\n\n#获取病毒科技树\nget_plague_tech_info 20108 {\n    request {\n        id 0 : integer #活动id\n    }\n    response {\n        .info {\n            techid          0 : integer #科技类型\n            level       1 : integer #等级\n        }\n        result  0 : integer #0 失败,活动时间未到\n        list    1 : *info\n    }\n}\n\n#升级科技树\nplague_tech_levelup 20109 {\n    request {\n        id      0 : integer #活动id\n        techid  1 : integer #要科技id\n    }\n    response {\n        result      0 : integer # 0 失败 1 成功 2 失败 需要前置技能 3 失败 等级上限 4 因子数量不足 5 配置错误 6 失败 上层科技等级不足\n        techid      1 : integer #科技类型\n        level       2 : integer #当前等级\n        cost_items  3 : *consumeids#消耗因子数量\n    }\n}\n\n#重置科技树\nplague_tech_reset 20110 {\n    request {\n        id      0 : integer #活动id\n    }\n    response {\n        result  0 : integer # 1 成功 2 钻石不够\n        vif     1 : item  #获得物品\n        diamond 2 : integer #消耗的钻石\n    }\n}\n\n#城市重置\nplague_city_reset 20111 {\n    request {\n        id      0 : integer #活动id\n        cityid  1 : integer\n    }\n    response {\n        result  0 : integer\n        get     1 : item #代币\n    }\n}\n\n#获取技能信息\nplague_skill_info 20112 {\n    request {\n        id 0 : integer #活动id\n    }\n    response {\n        .skillinfo {\n            skillid 0 : integer\n            cd      1 : integer #时间戳\n        }\n        result  0 : integer\n        list    1 : *skillinfo\n    }\n}\n\n#使用技能\nplague_use_skill 20113 {\n    request {\n        id      0 : integer #活动id\n        cityid  1 : integer\n        nodeid  2 : integer\n        skillid 3 : integer #技能id\n    }\n    response {\n        result  0 : integer #0 失败,活动时间未到 1 成功 2 失败 冷却中 3 失败 物品不足 4 失败 技能不存在 5 失败,目标选择错误 6 钻石不足 7 目标节点还未投放病毒 8 目标节点已被完全破坏\n        skillid 1 : integer #\n        cd      2 : integer\n        cost_items 3 : *consumeids #消耗的物品信息\n        diamond 4 : integer #消耗的钻石\n    }\n}\n\n#清除技能cd\nplague_clear_skillcd 20114 {\n    request {\n        id      0 : integer\n        skillid 1 : integer\n    }\n    response {\n        result  0 : integer # 1 成功 2 失败 钻石不足\n        diamond 1 : integer #消耗的钻石\n    }\n}\n\n#恢复病毒\nplague_recover_virus 20115 {\n    request {\n        id  0 : integer #活动id\n    }\n    response {\n        result      0 : integer # 1 成功\n        lastrecover 1 : integer #最后一次恢复时间\n        virus       2 : item #病毒物品 有可能为null\n    }\n}\n\n#购买或使用道具增加病毒\nplague_add_virus 20116 {\n    request {\n        id      0 : integer #活动id\n        type    1 : integer #类型 1 道具 2 钻石\n    }\n    response {\n        result      0 : integer # 1 成功 2 物品不足 3 购买次数不 4 钻石不足\n        virus       1 : item #病毒  有可能为null\n        diamond     2 : integer #消耗的钻石\n        consumes    3 : *consumeids #物品消耗信息\n        virusbuy    4 : integer #剩余购买次数\n    }\n}\n\n#AI战斗(104*)\n\npass_aiattack 10400 {\n    request {\n        mode 0 : integer\n        .cost_item {\n            itemid 0 : integer\n            num 1 : integer\n        }\n        cost_items 2 : *cost_item\n    }\n    response {\n        result 0 : integer\n        gold 1 : integer\n        items 2 : *item\n        curlevel 3 : string\n        curmode 4 : integer\n        levelmode 5 : modeconfig\n        gainitems 6 : *item\n    }\n}\n\nswitch_to_aiattack 10401 {\n    request {\n        mode 0 : integer\n        chapter 1 : integer\n    }\n    response {\n        result 0 : integer\n        curlevel 1 : string\n        curmode 2 : integer\n        levelmode 3 : modeconfig\n    }\n}\n\n#三星关卡(105*)\n\nrepeat_pass_big_boss 10500 {\n    request {\n        mode 0 : integer\n        level 1 : string  #第几关\n        token 2 : string\n        fight_array 3 : *fight_array_info\n        fighttime 4 : integer\n    }\n    response {\n        result 0 : integer\n        exp 1 : string\n        grade 2 : integer\n        gold 3 : integer\n        items 4 : *item\n        curlevel 5 : string\n        curmode 6 : integer\n        levelmode 7 : mod