态\ncheck_guide_stat 3904 {\n    request {\n        id  0 : integer\n    }\n    response {\n        result 0 : integer\n    }\n}\n\n#重置指引行为状态\nreset_guide_stat 3905 {\n    request {\n        id  0 : integer\n    }\n    }\n\n#获取完成指引行为后奖励\nget_guide_reward 3906 {\n    request {\n        id  0 : integer\n    }\n    response {\n        result  0 : integer\n        gold    1 : integer\n        diamond 2 : integer\n        sp      3 : integer\n        honor   4 : integer\n        items   5 : *item\n    }\n}\n\n#[宿舍]一键领取好感币\nadd_favor_one_key 4701 {\n    response {\n        result 0 : integer\n        back_gift 1 : back_gift\n    }\n}\n\n# 发送手机验证码\nsend_sms_code 5901 {\n    request {\n        phone 0 : string\n    }\n    response {\n        result 0 : integer\n    }\n}\n\n# 验证手机验证码\nverify_sms_code 5902 {\n    request {\n        code  0 : string\n    }\n    response {\n        result 0 : integer\n        items  1 : *item\n    }\n}\n# 芯片熔炼和构筑\nbreak_remake_component 670 {\n    request {\n        entityids 0 : *integer\n        isbreak 1 : boolean\n    }\n    response {\n        result 0 : integer\n        num 1 : integer\n        consumeids 2 : *consumeids\n        getitem 3 : item\n    }\n}\n\n# 一键共振(快速共振)\none_key_servant_breakout 350 {\n    request {\n        servants 0 : *integer\n    }\n    response {\n        .servantsInfo{\n            servantid 0 : integer\n            consumes 1 : *consumeids    # 消耗材料\n            consume_servant_cardNum 2 : integer     # 消耗的角色数量\n            contract_count 3 : integer      # 该角色共振次数\n        }\n        result 0 : integer\n        servantsInfos 1 : *servantsInfo\n    }\n}\n\nset_old_player_guide 351 {\n    response {\n        result 0 : integer\n    }\n}\n"
